-- Seven new compliance items from sources read in full on the official pages on 26 Nov 2026 (Framework v0.4, Appendix C.2), plus the 12 register sources they cite.
-- Insert-only and idempotent: an item is added only if no item with the same name exists. Existing items, dates, history and wording are never changed.
-- legal_sources rows are upserted (the register is a record of what was read).
insert into public.legal_sources (key,name,kind,provisions_read,version_and_date_read,status,url,notes,checked_on) values
($q$FENZSS$q$,$q$FENZ: Fire Seasons, Fire Danger and permits$q$,$q$official guidance$q$,$q$whole page: open, restricted and prohibited seasons, who declares them, public conservation land, fire danger advice$q$,$q$no page date shown; read in full 26 Nov 2026 in Chrome (the old address redirects here)$q$,$q$Verified – official guidance (read in full)$q$,$q$https://www.fireandemergency.nz/outdoor-and-rural-fire-safety/what-are-the-fire-seasons/$q$,$q$Archive copy: https://web.archive.org/web/20261125162542/https://www.fireandemergency.nz/outdoor-and-rural-fire-safety/what-are-the-fire-seasons/$q$,date '2026-11-26'),
($q$FENZFP$q$,$q$FENZ: Open air fire rules$q$,$q$official guidance$q$,$q$whole page: safety requirements by fire type in restricted and prohibited seasons, including cultural cooking fires$q$,$q$no page date shown; read in full 26 Nov 2026 in Chrome (the old address redirects here)$q$,$q$Verified – official guidance (read in full)$q$,$q$https://www.fireandemergency.nz/outdoor-and-rural-fire-safety/what-are-the-fire-seasons/open-air-fire-rules/$q$,$q$Archive copy: https://web.archive.org/web/20261125162426/https://www.fireandemergency.nz/outdoor-and-rural-fire-safety/what-are-the-fire-seasons/open-air-fire-rules/$q$,date '2026-11-26'),
($q$HNZHEAT$q$,$q$Health NZ: Health effects from heat$q$,$q$official guidance$q$,$q$whole page text: keeping cool, who is at risk, heat health plan guidelines; the expandable heatwave sections (preparing, during, after) were not opened$q$,$q$resources reviewed October and November 2026; read 26 Nov 2026 in Chrome (the old address redirects here)$q$,$q$Verified – official guidance (point checked)$q$,$q$https://www.healthnz.govt.nz/health-topics/keeping-healthy/healthy-homes-environments/health-effects-from-heat$q$,$q$Archive copy: https://web.archive.org/web/20261125162602/https://www.healthnz.govt.nz/health-topics/keeping-healthy/healthy-homes-environments/health-effects-from-heat$q$,date '2026-11-26'),
($q$MOJSL$q$,$q$Ministry of Justice: Special licences (alcohol)$q$,$q$official guidance$q$,$q$whole page: when a special licence is needed, who applies, 20 working days, unforeseen events, hours, objections, fees$q$,$q$page last updated 18 Dec 2020; now in the ministry's key-initiatives archive; read in full 26 Nov 2026 in Chrome$q$,$q$Verified – official guidance (read in full; archived page, may be out of date)$q$,$q$https://www.justice.govt.nz/justice-sector-policy/key-initiatives/key-initiatives-archive/sale-and-supply-of-alcohol/licensing/special-licences/$q$,$q$Archive copy: https://web.archive.org/web/20261125162811/https://www.justice.govt.nz/justice-sector-policy/key-initiatives/key-initiatives-archive/sale-and-supply-of-alcohol/licensing/special-licences/$q$,date '2026-11-26'),
($q$DIAGC$q$,$q$Department of Internal Affairs: Classes of Gambling$q$,$q$official guidance$q$,$q$whole page: class 1, 2, 3 and 4 and private gambling$q$,$q$no page date shown; mentions the Online Casino Gambling Act 2026; read in full 26 Nov 2026 in Chrome (the old address no longer works)$q$,$q$Verified – official guidance (read in full)$q$,$q$https://www.dia.govt.nz/Services-Casino-and-Non-Casino-Gaming-Classes-of-Gambling$q$,$q$Archive copy: https://web.archive.org/web/20261125162833/https://www.dia.govt.nz/Services-Casino-and-Non-Casino-Gaming-Classes-of-Gambling$q$,date '2026-11-26'),
($q$WSEVR$q$,$q$WorkSafe: Managing risks at events$q$,$q$official guidance$q$,$q$whole page: PCBU duties at events, no transfer of duties, overlapping duties, hazards, risk assessment, control measures, records$q$,$q$page last updated 5 Oct 2023 (noted 25 Nov; no date in the 26 Nov text); read in full 26 Nov 2026 in Chrome$q$,$q$Verified – official guidance (read in full)$q$,$q$https://www.worksafe.govt.nz/topic-and-industry/event-management/managing-risks-at-events/$q$,$q$Archive copy: https://web.archive.org/web/20261125162744/https://www.worksafe.govt.nz/topic-and-industry/event-management/managing-risks-at-events/$q$,date '2026-11-26'),
($q$WSELEC$q$,$q$WorkSafe: Low and extra low voltage electrical installations$q$,$q$official guidance$q$,$q$whole page: AS/NZS 3000:2018 from 13 November 2026, testing and certification, regulation 20 unsafe installations, inspection, warrant of electrical fitness (regulations 76 to 78 named), reconnection$q$,$q$page dated 24 November 2026 (the page showed 19 December 2025 on 25 Nov); read in full 26 Nov 2026 in Chrome$q$,$q$Verified – official guidance (read in full)$q$,$q$https://www.worksafe.govt.nz/topic-and-industry/electricity/installations-and-networks/low-voltage-electrical-installations/$q$,null,date '2026-11-26'),
($q$ESR10$q$,$q$Electricity (Safety) Regulations 2010 (SR 2010/36)$q$,$q$legislation$q$,$q$regulations 7 and 75 to 78 read in full; the definition of relocatable building is in the Electricity Act 1992 (ELACT92)$q$,$q$version as at 15 January 2026; official PDF supplied by John, read 25 Nov 2026$q$,$q$Verified – primary source (regulations), point checked, parts read in full$q$,$q$https://legislation.govt.nz/secondary-legislation/pco-drafted/2010/36/en/2026-01-15.pdf$q$,null,date '2026-11-26'),
($q$ASBREG$q$,$q$Health and Safety at Work (Asbestos) Regulations 2016 (LI 2016/15)$q$,$q$legislation$q$,$q$regulations 3 to 14 first by fetch summary; regulations 7, 10, 13, 14, 21, 22, 25, 26, 27, 34 and 54 to 57 read in the official PDF; the other regulations not examined closely$q$,$q$version 34.0 as at 30 March 2025; official PDF supplied by John, read 25 Nov 2026$q$,$q$Verified – primary source (regulations), point checked, parts only$q$,$q$https://www.legislation.govt.nz/secondary-legislation/pco-drafted/2016/15/en/latest/$q$,null,date '2026-11-26'),
($q$FENZOFF$q$,$q$Fire and Emergency New Zealand (Offences) Regulations 2018$q$,$q$legislation$q$,$q$regulations 5 to 7 and Schedules 2 and 3 read in full (infringement and strict liability offences, including Act ss 57(1), 58(1), 59(2), 60(1), 61(2))$q$,$q$version 13.0 as named on the official PDF supplied by John, in force 13 December 2018; read 25 Nov 2026$q$,$q$Verified – primary source (regulations), read in full$q$,$q$https://www.legislation.govt.nz/secondary-legislation/pco-drafted/2018/229/en/latest/$q$,null,date '2026-11-26'),
($q$FENZ17B$q$,$q$Fire and Emergency New Zealand Act 2017$q$,$q$legislation$q$,$q$sections 52 to 61 read in full: prohibitions and restrictions, fire seasons, fires in open air, permits, offences and court maximums$q$,$q$version 136.0 as at 2 November 2026; official PDF supplied by John, read 25 Nov 2026$q$,$q$Verified – primary source (Act), sections 52 to 61 only$q$,$q$https://www.legislation.govt.nz/act/public/2017/17/en/latest/$q$,null,date '2026-11-26'),
($q$WSASBG$q$,$q$WorkSafe: Managing asbestos in your building or workplace, Good Practice Guidelines for PCBUs (84 pages)$q$,$q$official guidance$q$,$q$sections 1, 2.1 to 2.4, 5.1 to 5.10, 6, 7.17, 8.4 to 8.6 and glossary entries for PCBU, other persons at the workplace and worker read in full; sections 2.5, 3, 4, 5.11, 5.12, 7.1 to 7.16, 8.1 to 8.3 and the appendices not read$q$,$q$April 2026; read 25 Nov 2026 from the PDF supplied by John; the link was opened on 26 Nov 2026 and is the WorkSafe page for this guideline$q$,$q$Verified – official guidance, sections named read in full$q$,$q$https://www.worksafe.govt.nz/topic-and-industry/asbestos/information-for-businesses-organisations-and-building-owners/managing-asbestos-in-your-building-or-workplace-for-pcbus/$q$,$q$Archive copy: https://web.archive.org/web/20261125162958/https://www.worksafe.govt.nz/topic-and-industry/asbestos/information-for-businesses-organisations-and-building-owners/managing-asbestos-in-your-building-or-workplace-for-pcbus/$q$,date '2026-11-26')
on conflict (key) do update set name=excluded.name, kind=excluded.kind, provisions_read=excluded.provisions_read, version_and_date_read=excluded.version_and_date_read, status=excluded.status, url=excluded.url, notes=excluded.notes, checked_on=excluded.checked_on;

insert into public.compliance_items (category, name, renewal_months, notes, classification, legal_basis, legal_basis_detail, stage)
select v.category, v.name, v.renewal_months, v.notes, v.classification, v.legal_basis, v.legal_basis_detail, v.stage
from (values
  ($q$emergency_preparedness$q$,$q$Fire season checked before lighting any outdoor fire (hāngī, bonfire, barbecue)$q$,null,$q$Framework v0.4, 4.3 · Applies if: the marae lights any fire in the open air (hāngī, umu, bonfire, campfire, barbecue). · Verification: Verified – primary source and official guidance. · Frequency: Before each fire; check on the day at checkitsalright.nz. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Fire and Emergency New Zealand Act 2017, ss 57 and 58 (fire seasons), if the marae lights any fire in the open air$q$,$q$Lighting a fire in the open air is not allowed in a prohibited fire season, and in a restricted season it needs a permit unless the fire type is authorised. A hāngī is an authorised fire type in both seasons if the fire area is under 4 square metres, at least 5 metres from any building or anything that could burn, a way to put it out is within 5 metres, it is never left unattended, and it is put out once the stones reach cooking temperature, before cooking starts. Read in full on the official pages (26 Nov 2026). Confirmed on an official agency page (read in full 26 Nov 2026).$q$,1),
  ($q$building$q$,$q$Certificates of Compliance kept for any new or altered electrical work$q$,null,$q$Framework v0.4, 3.2 · Applies if: any electrical work is done at the marae. · Verification: Verified – official guidance (WorkSafe page read in full 26 Nov 2026); regulations 75 to 78 read from the official PDF. · Frequency: Each time electrical work is done. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Electricity (Safety) Regulations 2010, testing and certification of installation work, if any electrical work is done at the marae$q$,$q$New electrical installation work must be tested and certified. From 13 November 2026 electrical workers must use AS/NZS 3000:2018 and every Certificate of Compliance must name that version. A Certificate of Verification is needed if an installation has been disconnected for more than six months. Good practice: ask the electrician for the certificate and keep it with the building records. Confirmed on an official agency page (read in full 26 Nov 2026).$q$,2),
  ($q$health_safety$q$,$q$Asbestos checked in any building built before 2000, with a management plan if it is present$q$,60,$q$Framework v0.4, 3.2 · Applies if: the marae is a business or undertaking (for example it employs anyone); otherwise good practice. · Verification: Partly verified (some guideline sections not read). · Frequency: Plan reviewed at least every 5 years and when asbestos is disturbed. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Health and Safety at Work (Asbestos) Regulations 2016, if the marae is a business or undertaking (for example it employs anyone); otherwise good practice$q$,$q$WorkSafe says buildings built before 1 January 2000 are likely to contain asbestos. Where it is present or likely, a written management plan must exist, be reviewed at least every five years, and be available to workers and others working there. Before demolition or refurbishment a competent person must inspect. A marae with no employees is probably not a business or undertaking, so this is good practice for it. Partly confirmed; part of this is still being checked.$q$,2),
  ($q$other$q$,$q$Special licence arranged for any event where alcohol is sold, or an entry fee or koha is charged$q$,null,$q$Framework v0.4, Hosting and hiring the marae · Applies if: alcohol is sold or supplied at an event and an entry fee or koha is charged. · Verification: Partly verified (Ministry page read in full; the Act itself not yet read; the page is archived and dated 2020). · Frequency: Each event; apply at least 20 working days before. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Ministry of Justice special licence guidance (Sale and Supply of Alcohol Act 2012), if alcohol is sold or supplied at an event with an entry fee or koha$q$,$q$Apply to the local council at least 20 working days before the event. For an unexpected event such as a tangi the committee can consider it faster. Whether alcohol is allowed on the marae at all is a matter of tikanga and kawa, not law. The Ministry page is archived and dated 2020, and the Act itself has not yet been read. Partly confirmed; part of this is still being checked.$q$,2),
  ($q$other$q$,$q$Raffles and housie kept within the Department of Internal Affairs limits$q$,null,$q$Framework v0.4, Hosting and hiring the marae · Applies if: the marae runs a raffle, housie or similar fundraiser. · Verification: Partly verified (DIA page read in full; whether a marae counts as a society is not yet confirmed). · Frequency: Each fundraiser. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Gambling Act 2003, classes 1 to 3, if the marae runs a raffle, housie or similar fundraiser$q$,$q$Class 1 (prizes or turnover up to $500) and class 2 (prizes up to $5,000 and turnover up to $25,000, societies only) need no licence. Above that a class 3 licence is needed. Nobody can be paid for running class 1 or 2 gambling, and proceeds must go to authorised purposes. Whether a marae counts as a society for this is still to be confirmed. Partly confirmed; part of this is still being checked.$q$,2),
  ($q$health_safety$q$,$q$Hire agreement says who is responsible for safety at hired events$q$,12,$q$Framework v0.4, Hosting and hiring the marae · Applies if: the marae hires out its buildings. · Verification: Verified – official guidance (read in full 26 Nov 2026); how duties divide between venue owner and hirer is still to verify. · Frequency: Annual review. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Good practice: WorkSafe, Managing risks at events$q$,$q$A hirer who organises an event is likely to be a business or undertaking and cannot hand its safety duties to someone else. The marae sets its own rules for hirers: building limits, the evacuation scheme, and who does what. Good practice or a marae decision – not a legal requirement.$q$,3),
  ($q$emergency_preparedness$q$,$q$Hot weather plan for hui: water, shade, a cool space, checks on kaumātua$q$,12,$q$Framework v0.4, 4.3 · Applies if: all marae. · Verification: Verified – official guidance (page text read 26 Nov 2026). · Frequency: Before summer. · Evidence to keep: a document, minute or photo showing it is done. · Marae's own assessment, not legal advice.$q$,$q$task$q$,$q$Good practice: Health NZ, Health effects from heat$q$,$q$Babies, older people, people with health conditions and people living alone are most at risk in the heat. Plan drinking water and shade for manuhiri, a cool space, and a way of checking on kaumātua. Not a legal duty. Good practice or a marae decision – not a legal requirement.$q$,3)
) as v(category, name, renewal_months, notes, classification, legal_basis, legal_basis_detail, stage)
where not exists (select 1 from public.compliance_items i where i.name = v.name);

update public.compliance_items i set framework_class = v.fc, source_keys = v.keys
from (values
  ($q$Fire season checked before lighting any outdoor fire (hāngī, bonfire, barbecue)$q$,$q$conditional_legal$q$,array['FENZ17B','FENZOFF','FENZSS','FENZFP']),
  ($q$Certificates of Compliance kept for any new or altered electrical work$q$,$q$conditional_legal$q$,array['WSELEC','ESR10']),
  ($q$Asbestos checked in any building built before 2000, with a management plan if it is present$q$,$q$conditional_legal$q$,array['WSASBG','ASBREG']),
  ($q$Special licence arranged for any event where alcohol is sold, or an entry fee or koha is charged$q$,$q$conditional_legal$q$,array['MOJSL']),
  ($q$Raffles and housie kept within the Department of Internal Affairs limits$q$,$q$conditional_legal$q$,array['DIAGC']),
  ($q$Hire agreement says who is responsible for safety at hired events$q$,$q$good_practice$q$,array['WSEVR']),
  ($q$Hot weather plan for hui: water, shade, a cool space, checks on kaumātua$q$,$q$good_practice$q$,array['HNZHEAT'])
) as v(name, fc, keys)
where i.name = v.name and i.source_keys = '{}' and i.framework_class is null;
